package com.smartmart.inventory.controller;
import com.smartmart.inventory.dto.*; import com.smartmart.inventory.service.InventoryService; import jakarta.validation.Valid; import lombok.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/inventory") @RequiredArgsConstructor public class InventoryController {private final InventoryService s; @PostMapping @PreAuthorize("hasRole('MANAGER')") ResponseEntity<InventoryResponse> create(@Valid @RequestBody InventoryRequest r){return ResponseEntity.status(201).body(s.create(r));} @GetMapping public List<InventoryResponse> all(){return s.all();} @GetMapping("/{id}") public InventoryResponse one(@PathVariable Long id){return s.one(id);}@GetMapping("/product/{id}") public InventoryResponse product(@PathVariable Long id){return s.product(id);}@PutMapping("/{id}") @PreAuthorize("hasRole('MANAGER')") public InventoryResponse update(@PathVariable Long id,@Valid @RequestBody InventoryRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('MANAGER')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}@GetMapping("/low-stock") public List<InventoryResponse> low(){return s.low();}@GetMapping("/expiring") public List<InventoryResponse> exp(){return s.expiring();}@GetMapping("/discounted") @PreAuthorize("hasRole('MANAGER')") public List<InventoryResponse> disc(){return s.discounted();}@PostMapping("/{id}/restock") @PreAuthorize("hasRole('MANAGER')") public InventoryResponse restock(@PathVariable Long id,@Valid @RequestBody RestockRequest r){return s.restock(id,r);}@PostMapping("/{id}/adjust") @PreAuthorize("hasRole('MANAGER')") public InventoryResponse adjust(@PathVariable Long id,@Valid @RequestBody AdjustStockRequest r){return s.adjustStock(id,r);}}
